#!/usr/bin/env node
/**
 * Build the app layer from the DTCG token files.
 *
 *   node scripts/build-tokens.js          write the generated files
 *   node scripts/build-tokens.js --check  write nothing; exit 1 if any generated file is
 *                                         stale, if tokens/foundation.tokens.json no
 *                                         longer matches colors_and_type.css, or if a
 *                                         hand-written stylesheet reads a custom property
 *                                         that is not a token
 *
 * Source:    tokens/foundation.tokens.json, tokens/app.tokens.json
 * Generated: app-tokens.css           custom properties for any web app (light + dark)
 *            app-fonts.css            the Google Fonts import, on its own, so an app that
 *                                     hosts its fonts itself leaves the file out
 *            tokens/tailwind.css      a Tailwind v4 @theme mapping onto those properties
 *            tokens/app.resolved.json every token resolved to a final value, per mode,
 *                                     for Python and other non-CSS consumers
 *
 * colors_and_type.css stays the hand-edited source for the marketing kit; the
 * foundation JSON mirrors it, and --check is what keeps the two from drifting.
 *
 * Dependency-free: Node 18+.
 */
'use strict';

const fs = require('fs');
const path = require('path');
const { ROOT, MODES, load, cssName, cssValue, formatValue } = require('./lib/tokens');

const FONT_IMPORT = "@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500&family=Lora:ital,wght@1,700&family=Poppins:ital,wght@0,400;0,500;0,600;0,700;1,400&display=swap');";
const BANNER = (source) => `/**
 * GENERATED by scripts/build-tokens.js from ${source} — do not edit by hand.
 * Edit the JSON, then run: node scripts/build-tokens.js
 */`;

function groupOf(key) {
  if (key.startsWith('theme.')) return 'theme';
  return key.startsWith('app.') || /^(color\.(success|warning|danger|chart)|color\.dark-blue\.450|color\.pink\.950|font\.mono|font-weight\.medium)/.test(key) ? 'app' : 'foundation';
}

// The fonts are a file of their own. A bundler inlines app-tokens.css, and an @import
// that lands mid-file is ignored by browsers; an app that hosts its own fonts had to
// strip the line on every copy (gui2 did). Now the tokens file copies as it is.
function buildFonts() {
  return [
    '/**',
    ' * GENERATED by scripts/build-tokens.js — do not edit by hand.',
    ' *',
    ' * Poppins, Lora Bold Italic and JetBrains Mono from Google Fonts. Link it before',
    ' * app-tokens.css, or leave it out and host the three families yourself.',
    ' */',
    FONT_IMPORT,
    '',
  ].join('\n');
}

function buildCss(byPath) {
  const sections = { foundation: [], app: [], light: [], dark: [] };
  for (const [key, entry] of byPath) {
    const line = `  ${cssName(key)}: ${cssValue(entry)};`;
    const g = groupOf(key);
    if (g === 'theme') sections[key.split('.')[1]].push(line);
    else sections[g].push(line);
  }
  const block = (selector, lines, extra = []) => `${selector} {\n${extra.concat(lines).join('\n')}\n}`;
  return [
    BANNER('tokens/*.tokens.json'),
    '/* No fonts are loaded here: add app-fonts.css, or host Poppins, Lora and JetBrains Mono yourself. */',
    '',
    '/* Foundation tokens — the same values as colors_and_type.css, repeated here so an app can load this file on its own. */',
    block(':root', sections.foundation),
    '',
    '/* App layer: new primitives, compact type and density. */',
    block(':root', sections.app),
    '',
    '/* Light (default). [data-theme="light"] also forces light on a subtree. */',
    block(':root,\n[data-theme="light"]', sections.light, ['  color-scheme: light;']),
    '',
    '/* Dark: on request, on a subtree, or from the OS unless the page asks for light. */',
    block('[data-theme="dark"]', sections.dark, ['  color-scheme: dark;']),
    '',
    '@media (prefers-color-scheme: dark) {',
    block('  :root:not([data-theme="light"])', sections.dark.map((l) => '  ' + l), ['    color-scheme: dark;']).replace(/\n}$/, '\n  }'),
    '}',
    '',
  ].join('\n');
}

// Tailwind v4. Themed values (light/dark) are var() references, so switching
// data-theme re-themes every utility at runtime (@theme inline). Mode-invariant
// values are written as literals: the brand names (--color-navy, --radius-sm,
// --font-mono…) are the same names Tailwind's theme uses, and a var() pointing at
// its own name would be a cycle. Tailwind's default palette, fonts, radii and
// shadows are cleared, so only brand values exist as utilities.
const TW_GROUP = { surface: 'surface', text: 'fg', border: 'line', accent: 'accent' };
const FOUNDATION_SHORTCUTS = /^color\.(bg-|text-|cta-|graph|icon-bg)/;
function buildTailwind(byPath) {
  const lines = [];
  const seen = new Set();
  const add = (name, value) => { if (!seen.has(name)) { seen.add(name); lines.push(`  ${name}: ${value};`); } };
  const literal = (key) => formatValue(byPath.get(key).resolved);
  for (const ns of ['--color-*', '--font-*', '--radius-*', '--shadow-*']) add(ns, 'initial');
  lines.push('', '  /* Brand primitives (the same in both modes) */');
  for (const [key, entry] of byPath) {
    if (!key.startsWith('color.') || entry.resolved.type !== 'color' || FOUNDATION_SHORTCUTS.test(key)) continue;
    add(cssName(key), literal(key));
  }
  lines.push('', '  /* Semantic colours (light and dark, from app-tokens.css) */');
  for (const key of byPath.keys()) {
    const m = key.match(/^theme\.light\.(.+)$/);
    if (!m || byPath.get(key).resolved.type !== 'color') continue;
    const parts = m[1].split('.');
    let twParts;
    if (parts[0] === 'app' && TW_GROUP[parts[1]]) twParts = [TW_GROUP[parts[1]], ...parts.slice(2)];
    else if (parts[0] === 'app' && parts[1] === 'status') twParts = parts.slice(2);
    else if (parts[0] === 'app') twParts = parts.slice(1);
    else twParts = parts; // viz.*
    if (twParts[twParts.length - 1] === 'default') twParts.pop();
    let name = `--color-${twParts.join('-')}`;
    if (name === '--color-surface-canvas') name = '--color-canvas';
    add(name, `var(${cssName(key)})`);
  }
  lines.push('', '  /* Type */');
  add('--font-sans', literal('font.primary'));
  add('--font-serif', literal('font.accent'));
  add('--font-mono', literal('font.mono'));
  for (const key of byPath.keys()) {
    const m = key.match(/^app\.font-size\.(.+)$/);
    if (m) {
      add(`--text-app-${m[1]}`, literal(key));
      add(`--text-app-${m[1]}--line-height`, literal(`app.line-height.${m[1]}`));
    }
  }
  lines.push('', '  /* Shape and depth */');
  for (const key of byPath.keys()) {
    const m = key.match(/^(?:radius|app\.radius)\.(.+)$/);
    if (m && byPath.get(key).resolved.type === 'dimension') add(`--radius-${m[1]}`, literal(key));
  }
  add('--shadow-overlay', 'var(--app-shadow-overlay)');
  lines.push('', "  /* Layout: wide:… applies from 1200px (md is Tailwind's own 768px); max-w-content */");
  const px = (key) => byPath.get(key).resolved.value.value;
  if (px('app.breakpoint.md') !== 768) throw new Error("app.breakpoint.md must stay 768px: it is Tailwind's md, and the media queries in app-components.css");
  add('--breakpoint-wide', `${px('app.breakpoint.wide') / 16}rem`);
  add('--container-content', literal('app.width.content'));
  return [
    BANNER('tokens/*.tokens.json'),
    '/* Tailwind v4 theme for the Protect Line app layer.',
    ' *',
    ' *   @import "tailwindcss";',
    ' *   @import "<path>/app-tokens.css";',
    ' *   @import "<path>/tokens/tailwind.css";',
    ' *',
    ' * Fonts: link app-fonts.css from the page head, or host Poppins, Lora and JetBrains',
    ' * Mono in the app. Do not @import app-fonts.css here: a bundler would inline it mid-file,',
    ' * where browsers ignore an @import url(...).',
    ' *',
    ' * Utilities: bg-canvas bg-surface bg-surface-raised text-fg text-fg-muted border-line',
    ' * bg-accent text-fg-on-accent bg-success-bg text-success-fg fill-viz-cat-1 text-app-sm',
    ' * font-mono rounded-control rounded-panel rounded-pill shadow-overlay bg-navy text-hot-pink',
    ' * wide:grid max-w-content z-(--app-layer-sticky). */',
    '@theme inline {',
    ...lines,
    '}',
    '',
  ].join('\n');
}

function buildResolved(byPath) {
  const out = {
    $description: 'GENERATED by scripts/build-tokens.js. Every token resolved to its final CSS value, once per mode. Keys are token paths with the theme.<mode>. prefix removed. For Python and other non-CSS consumers.',
  };
  for (const mode of MODES) {
    const flat = {};
    for (const [key, entry] of byPath) {
      const m = key.match(/^theme\.(light|dark)\.(.+)$/);
      if (m && m[1] !== mode) continue;
      flat[m ? m[2] : key] = formatValue(entry.resolved);
    }
    out[mode] = Object.fromEntries(Object.entries(flat).sort(([a], [b]) => a.localeCompare(b)));
  }
  return JSON.stringify(out, null, 2) + '\n';
}

/** Compare the foundation JSON with the :root block of colors_and_type.css. */
function foundationDrift(byPath) {
  const css = fs.readFileSync(path.join(ROOT, 'colors_and_type.css'), 'utf8');
  const root = css.match(/:root\s*\{([\s\S]*?)\n\}/);
  if (!root) return ['colors_and_type.css: no :root block found'];
  // Quote style is not significant: 'Poppins', Arial and 'Poppins', 'Arial' are the same font list.
  const norm = (v) => v.trim().toLowerCase().replace(/['"]/g, '');
  const fromCss = new Map([...root[1].matchAll(/(--[a-z0-9-]+)\s*:\s*([^;]+);/g)].map((m) => [m[1], norm(m[2])]));
  const fromJson = new Map();
  for (const [key, entry] of byPath) if (groupOf(key) === 'foundation') fromJson.set(cssName(key), norm(cssValue(entry)));
  const problems = [];
  for (const [name, value] of fromCss) {
    if (!fromJson.has(name)) problems.push(`${name} is in colors_and_type.css but not in tokens/foundation.tokens.json`);
    else if (fromJson.get(name) !== value) problems.push(`${name}: colors_and_type.css has "${value}", tokens/foundation.tokens.json has "${fromJson.get(name)}"`);
  }
  for (const name of fromJson.keys()) if (!fromCss.has(name)) problems.push(`${name} is in tokens/foundation.tokens.json but not in colors_and_type.css`);
  return problems;
}

/**
 * Every var(--name) the hand-written stylesheets read must be a token, or be set in the
 * same file (a component's own --_h, the page's --pl-page-pad-x). A misspelt or renamed
 * token does not error in CSS: the declaration is dropped and the browser's default
 * shows. That fails quietly, so it is checked here. A var() with a fallback is left
 * alone: that is a value the page passes in (the progress bar's --value).
 */
const HAND_WRITTEN = ['components/app-components.css', 'tokens/shadcn.css', 'preview/app-preview.css'];
function unknownVars(tokensCss) {
  const defined = (css) => new Set([...css.matchAll(/(--[a-zA-Z0-9_-]+)\s*:/g)].map((m) => m[1]));
  const tokens = defined(tokensCss);
  const problems = [];
  for (const rel of HAND_WRITTEN) {
    const file = path.join(ROOT, rel);
    if (!fs.existsSync(file)) { problems.push(`${rel} is missing`); continue; }
    const css = fs.readFileSync(file, 'utf8').replace(/\/\*[\s\S]*?\*\//g, '');
    const own = defined(css);
    const unknown = new Set([...css.matchAll(/var\(\s*(--[a-zA-Z0-9_-]+)\s*\)/g)].map((m) => m[1]).filter((n) => !tokens.has(n) && !own.has(n)));
    for (const name of unknown) problems.push(`${rel} reads ${name}, which is not a token and is not set in that file`);
  }
  return problems;
}

function main() {
  const check = process.argv.includes('--check');
  let byPath;
  try {
    ({ byPath } = load());
  } catch (err) {
    console.error(`Token error: ${err.message}`);
    process.exit(1);
  }
  const outputs = {
    'app-tokens.css': buildCss(byPath),
    'app-fonts.css': buildFonts(),
    'tokens/tailwind.css': buildTailwind(byPath),
    'tokens/app.resolved.json': buildResolved(byPath),
  };
  const drift = foundationDrift(byPath);
  const unknown = unknownVars(outputs['app-tokens.css']);
  if (check) {
    let failed = false;
    for (const [rel, content] of Object.entries(outputs)) {
      const file = path.join(ROOT, rel);
      const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
      if (current !== content) {
        failed = true;
        console.error(`STALE  ${rel} — run: node scripts/build-tokens.js`);
      } else {
        console.log(`ok     ${rel}`);
      }
    }
    if (drift.length) {
      failed = true;
      console.error('DRIFT  tokens/foundation.tokens.json vs colors_and_type.css:');
      for (const p of drift) console.error(`       ${p}`);
    } else {
      console.log('ok     tokens/foundation.tokens.json matches colors_and_type.css');
    }
    if (unknown.length) {
      failed = true;
      console.error('UNKNOWN custom properties:');
      for (const p of unknown) console.error(`       ${p}`);
    } else {
      console.log(`ok     every var() in ${HAND_WRITTEN.join(', ')} is defined`);
    }
    process.exit(failed ? 1 : 0);
  }
  for (const [rel, content] of Object.entries(outputs)) {
    fs.writeFileSync(path.join(ROOT, rel), content);
    console.log(`wrote  ${rel}`);
  }
  if (drift.length) {
    console.error('WARNING: tokens/foundation.tokens.json does not match colors_and_type.css:');
    for (const p of drift) console.error(`  ${p}`);
    process.exit(1);
  }
}

main();
